def _governance_preflight():
    """Fail-closed (F3-2): refuse to start if a governance substrate is missing.
    The CCAS gate, the hash-chained audit and the contract validator are what the
    agent claims to enforce; if any cannot load, it must not serve. Override for
    local debugging ONLY via DOER_ALLOW_DEGRADED=1 (never in production)."""
    import os, sys
    problems = []
    for _label, _mod, _attr in (
        ("ccas_gate.ccas_decide (tier authorization)", "src.shared.ccas_gate", "ccas_decide"),
        ("hexa_record.log_event (hash-chained audit)", "src.shared.hexa_record", "log_event"),
        ("ceve_runtime.validate_contract (contract enforcement)", "src.shared.ceve_runtime", "validate_contract"),
    ):
        try:
            _m = __import__(_mod, fromlist=[_attr]); getattr(_m, _attr)
        except Exception as _e:
            problems.append(f"{_label}: {_e}")
    if problems and os.environ.get("DOER_ALLOW_DEGRADED") != "1":
        sys.stderr.write("FATAL: governance incomplete — refusing to start (fail-closed):\n")
        for _p in problems:
            sys.stderr.write(f"  - {_p}\n")
        sys.stderr.write("Set DOER_ALLOW_DEGRADED=1 to override (NOT for production).\n")
        raise SystemExit(3)


_governance_preflight()

