def _mo_event_type(composite):
    """Fas 2.10b — MO-eventets typfält: pipelinens klassificering när den
    finns, annars ÄRLIG fallback till disposition/status (aggregatet räknar
    då utfall — verklig signal, aldrig informationstomt). Enda källan för
    MO-eventets event_type; det emitterade kohorttestet importerar och
    använder samma funktion."""
    if not isinstance(composite, dict):
        return "unclassified"
    for key in ("event_type", "incident_type", "classification"):
        v = composite.get(key)
        if isinstance(v, str) and v.strip():
            return v.strip()
    inner = composite.get("payload")
    if isinstance(inner, dict):
        for key in ("event_type", "incident_type", "classification"):
            v = inner.get(key)
            if isinstance(v, str) and v.strip():
                return v.strip()
    for key in ("disposition", "status"):
        v = composite.get(key)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return "unclassified"


