# ── Fas 3.17 — REQUEST INTAKE LIMITS (contract fuzzing, red-team A21) ──────
# Fuzzing the emitted contract surface found no 5xx anywhere - malformed input
# already lands on 422, which is the property this phase set out to check. It
# found two other things instead:
#
#   * There was NO body size limit. A 64 MB request was accepted with 200, fully
#     buffered in memory before any handler ran. Any caller the transport lets
#     through can do that repeatedly.
#   * Python's json parser accepts the NON-STANDARD tokens NaN, Infinity and
#     -Infinity, and accepts lone UTF-16 surrogates. Both were accepted with
#     200, which means such a value can reach the hashed audit core. RFC 8259
#     has no NaN or Infinity, so an auditor re-serialising that record with a
#     strict parser gets a different byte string - or an error. A record that
#     cannot be re-read is not evidence, so this is an integrity property, not
#     a nicety.
#
# Enforced as pure ASGI middleware rather than BaseHTTPMiddleware so the body
# is buffered ONCE and replayed downstream explicitly, and so a chunked request
# with no Content-Length is measured as it arrives instead of being trusted.
MAX_REQUEST_BYTES = int(os.environ.get("DOER_MAX_REQUEST_BYTES", str(1024 * 1024)) or 1024 * 1024)

_JSON_NON_STANDARD = ("NaN", "Infinity", "-Infinity")


def _reject_non_standard(token):
    raise ValueError("non-standard JSON token %r is not permitted (RFC 8259)" % token)


class RequestIntakeLimits:
    """Bounds the body and refuses JSON that cannot round-trip."""

    def __init__(self, app):
        self.app = app

    async def _refuse(self, send, status, detail):
        body = json.dumps({"detail": detail}).encode("utf-8")
        await send({"type": "http.response.start", "status": status,
                    "headers": [(b"content-type", b"application/json"),
                                (b"content-length", str(len(body)).encode("ascii"))]})
        await send({"type": "http.response.body", "body": body})

    async def __call__(self, scope, receive, send):
        if scope.get("type") != "http" or scope.get("method") not in ("POST", "PUT", "PATCH"):
            await self.app(scope, receive, send)
            return

        headers = {k.decode("latin-1").lower(): v.decode("latin-1")
                   for k, v in scope.get("headers") or []}
        declared = headers.get("content-length")
        if declared and declared.isdigit() and int(declared) > MAX_REQUEST_BYTES:
            await self._refuse(send, 413, "request body exceeds %d bytes" % MAX_REQUEST_BYTES)
            return

        chunks = []
        total = 0
        more = True
        while more:
            message = await receive()
            if message["type"] != "http.request":
                break
            chunk = message.get("body") or b""
            total += len(chunk)
            # Measured as it arrives: a chunked request declares no length, so
            # trusting the header alone would leave the limit optional.
            if total > MAX_REQUEST_BYTES:
                await self._refuse(send, 413, "request body exceeds %d bytes" % MAX_REQUEST_BYTES)
                return
            chunks.append(chunk)
            more = message.get("more_body", False)
        body = b"".join(chunks)

        if body and "json" in (headers.get("content-type") or ""):
            try:
                text = body.decode("utf-8")
            except UnicodeDecodeError as e:
                await self._refuse(send, 422, "request body is not valid UTF-8: %s" % e)
                return
            try:
                text.encode("utf-8", "strict")
            except UnicodeEncodeError:
                await self._refuse(
                    send, 422,
                    "request body contains unpaired UTF-16 surrogates; such a value cannot be "
                    "re-serialised by a strict reader and must not enter the audit chain")
                return
            try:
                json.loads(text, parse_constant=_reject_non_standard)
            except ValueError as e:
                await self._refuse(send, 422, "malformed JSON: %s" % e)
                return

        replayed = {"sent": False}

        async def replay():
            if replayed["sent"]:
                return {"type": "http.disconnect"}
            replayed["sent"] = True
            return {"type": "http.request", "body": body, "more_body": False}

        await self.app(scope, replay, send)


