@app.get("/api/autonomy")
async def autonomy(_zt: Optional[Dict[str, Any]] = Depends(zt_guard(ZT_SCOPE_AUTONOMY))):

    stats = get_state().get_stats()
    auto = stats.get("auto_approved", 0)
    pending = stats.get("pending_approval", 0)
    escalated = stats.get("escalated", 0)
    total_actions = auto + pending + escalated
    autonomy_pct = round(100 * auto / total_actions) if total_actions else 100
    return {
        "autonomy_pct": autonomy_pct,
        "events_ingested": stats.get("events_ingested", 0),
        "incidents_classified": stats.get("incidents_classified", 0),
        "auto_approved": auto,
        "pending_approval": pending,
        "escalated": escalated,
        "denied": stats.get("denied", 0),
        "pii_blocks": stats.get("pii_blocks", 0),
        "errors": stats.get("errors", 0),
        "active_subscribers": stats.get("active_subscribers", 0),
        "started_at": stats.get("started_at"),
        "ts": _now_iso(),
    }


